from collections import deque

def topological_sort(edges, n):
    adj = {v: [] for v in range(1, n + 1)}

    for e in edges:
        adj[e[0]].append(e[1])

    sorted_list = []
    to_visit = deque((e, False) for e in range(1, n + 1))
    visiting = [False] * (n + 1)
    visited = [False] * (n + 1)

    while to_visit:
        e, v = to_visit.pop()

        if visited[e]:
            continue

        if v:
            sorted_list.append(e)
            visiting[e] = False
            visited[e] = True
        else:
            if visiting[e]:
                raise Exception("cycle detected.")

            visiting[e] = True
            to_visit.append((e, True))

            for e2 in adj[e]:
                to_visit.append((e2, False))

    sorted_list.reverse()
    return sorted_list

